arguments.new_string:
"""GSM8K reward: 1.0 when the last number in the response equals the reference answer."""
import re
from decimal import InvalidOperation

# Read the whole response: clipping to a fixed suffix can discard the final answer.
_NUMBER = re.compile(r"-?(?:\d+(?:,\d{3})*(?:\.\d*)?|\.\d+)")


def _as_decimal(text):
    from decimal import Decimal

    return Decimal(text.replace("\\$", "").replace("$", "").replace(",", "").strip())


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    matches = list(_NUMBER.finditer(solution_str.replace("\\$", "")))
    if not matches:
        return 0.0
    try:
        return float(_as_decimal(matches[-1].group()) == _as_decimal(str(ground_truth)))
    except InvalidOperation:
        return 0.0

